"""Golden cases and how a tool result is compared with them."""

from __future__ import annotations

import tomllib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


@dataclass(frozen=True)
class Case:
    tool: str
    arguments: dict[str, Any] = field(default_factory=dict)
    expect: str = ""


@dataclass(frozen=True)
class Mismatch:
    case: Case
    got: str


def load_cases(path: str | Path) -> list[Case]:
    with open(path, "rb") as fh:
        data = tomllib.load(fh)
    return [Case(c["tool"], dict(c.get("arguments", {})), c["expect"]) for c in data.get("case", [])]


def result_text(result: Any) -> str:
    """The text blocks of a tool result, joined with newlines."""
    return "\n".join(block.text for block in result.content if getattr(block, "type", None) == "text")


def compare(case: Case, result: Any) -> Mismatch | None:
    got = result_text(result)
    return None if got.strip() == case.expect.strip() else Mismatch(case, got)

from pathlib import Path

from mcp.types import CallToolResult, TextContent

from mcpcheck.cases import Case, Mismatch, compare, load_cases

EXAMPLES = Path(__file__).resolve().parent.parent / "examples" / "cases.toml"


def result(text: str) -> CallToolResult:
    return CallToolResult(content=[TextContent(type="text", text=text)])


def test_load_example_cases():
    assert load_cases(EXAMPLES) == [Case("add", {"a": 2, "b": 3}, "5"), Case("greet", {"name": "Ada"}, "Hello, Ada!")]


def test_compare():
    case = Case("greet", {"name": "Ada"}, "Hello, Ada!")
    assert compare(case, result("Hello, Ada!\n")) is None
    assert compare(case, result("Hi Ada")) == Mismatch(case, "Hi Ada")

